import Database from "better-sqlite3";
import { mkdirSync, readFileSync } from "node:fs";
import { dirname } from "node:path";

const file = process.env.DB_PATH ?? "data/absensi.db";
if (file !== ":memory:") mkdirSync(dirname(file), { recursive: true });

export const db = new Database(file);
db.pragma("journal_mode = WAL"); // pembaca tidak menunggu penulis
db.pragma("foreign_keys = ON"); // SQLite mematikannya secara bawaan
db.exec(readFileSync(new URL("../schema.sql", import.meta.url), "utf8"));

// Error yang membawa kode status. Contoh: throw gagal(404, "Sesi tidak ditemukan")
export const gagal = (status, message) => Object.assign(new Error(message), { status });

// Express 5 tidak membaca cookie sendiri. Nilai cookie kita base64url, jadi tidak perlu decode.
export function bacaCookie(req, name) {
  for (const part of (req.headers.cookie ?? "").split(";")) {
    const [key, ...rest] = part.trim().split("=");
    if (key === name) return rest.join("=");
  }
}

export const cookieAman = {
  httpOnly: true,
  sameSite: "lax",
  secure: process.env.NODE_ENV === "production",
};

