import { createHash, randomBytes, scrypt, timingSafeEqual } from "node:crypto";
import { promisify } from "node:util";
import { db } from "./db.js";
import { bacaCookie, cookieAman, gagal } from "./http.js";

const scryptAsync = promisify(scrypt);
// Parameter scrypt dari OWASP Password Storage Cheat Sheet (N=2^14, r=8, p=5), sekitar 16 MB per hash.
const SCRYPT = { N: 2 ** 14, r: 8, p: 5 };
const LOGIN_MS = 8 * 60 * 60 * 1000; // 8 jam, cukup untuk satu hari mengajar

export async function hashPassword(password) {
  const salt = randomBytes(16);
  const hash = await scryptAsync(password, salt, 64, SCRYPT);
  return `scrypt$${salt.toString("base64url")}$${hash.toString("base64url")}`;
}

export async function checkPassword(password, stored) {
  const [, salt, hash] = stored.split("$");
  const fresh = await scryptAsync(password, Buffer.from(salt, "base64url"), 64, SCRYPT);
  return timingSafeEqual(fresh, Buffer.from(hash, "base64url"));
}

const sha256 = (s) => createHash("sha256").update(s).digest("base64url");

export async function login(req, res) {
  const { email, password } = req.body ?? {};
  if (typeof email !== "string" || typeof password !== "string") throw gagal(400, "Email dan kata sandi wajib diisi");
  const user = db.prepare("SELECT id, password_hash FROM organizers WHERE email = ?").get(email.trim().toLowerCase());
  if (!user || !(await checkPassword(password, user.password_hash))) throw gagal(401, "Email atau kata sandi salah");

  const token = randomBytes(32).toString("base64url");
  db.prepare("DELETE FROM logins WHERE expires_at < ?").run(Date.now()); // bersihkan yang kedaluwarsa
  db.prepare("INSERT INTO logins (token_hash, organizer_id, expires_at) VALUES (?, ?, ?)")
    .run(sha256(token), user.id, Date.now() + LOGIN_MS);
  res.cookie("panitia", token, { ...cookieAman, maxAge: LOGIN_MS });
  res.json({ ok: true });
}

export function logout(req, res) {
  const token = bacaCookie(req, "panitia");
  if (token) db.prepare("DELETE FROM logins WHERE token_hash = ?").run(sha256(token));
  res.clearCookie("panitia", cookieAman);
  res.status(204).end();
}

// Middleware: hanya panitia yang sudah login boleh lewat.
export function wajibPanitia(req, res, next) {
  const token = bacaCookie(req, "panitia");
  const row = token && db.prepare("SELECT organizer_id FROM logins WHERE token_hash = ? AND expires_at > ?")
    .get(sha256(token), Date.now());
  if (!row) throw gagal(401, "Silakan login dulu");
  req.organizerId = row.organizer_id;
  next();
}

