import { createHmac, timingSafeEqual } from "node:crypto";

export const WINDOW_MS = 30_000; // QR berganti tiap 30 detik

const secret = process.env.QR_SECRET;
if (!secret || secret.length < 32) throw new Error("QR_SECRET wajib diisi di .env, minimal 32 karakter");

// Nomor jendela waktu: berapa kali 30 detik sudah lewat sejak 1 Januari 1970.
const windowOf = (now) => Math.floor(now / WINDOW_MS);
const sign = (sessionId, w) => createHmac("sha256", secret).update(`${sessionId}.${w}`).digest("base64url");

// Token = "idSesi.jendela.tandaTangan", contoh "12.59012345.Q2x...". Inilah isi QR.
export function makeToken(sessionId, now = Date.now()) {
  const w = windowOf(now);
  return { token: `${sessionId}.${w}.${sign(sessionId, w)}`, expiresIn: (w + 1) * WINDOW_MS - now };
}

export function verifyToken(token, now = Date.now()) {
  const m = /^(\d{1,9})\.(\d{1,12})\.([\w-]{43})$/.exec(String(token));
  if (!m) return { error: "QR tidak dikenali. Pastikan kamu memindai QR di layar kelas." };
  const [, sessionId, w, sig] = m;
  if (!timingSafeEqual(Buffer.from(sign(sessionId, w)), Buffer.from(sig))) {
    return { error: "QR tidak sah." };
  }
  // Terima jendela sekarang dan satu jendela sebelumnya, supaya yang memindai
  // di detik ke-29 tidak gagal karena jaringan lambat.
  const current = windowOf(now);
  if (Number(w) !== current && Number(w) !== current - 1) {
    return { error: "QR sudah kedaluwarsa. Pindai QR yang sedang tampil di layar." };
  }
  return { sessionId: Number(sessionId) };
}

import { Router } from "express";
import QRCode from "qrcode";
import { db } from "./db.js";
import { wajibPanitia } from "./auth.js";
import { gagal } from "./http.js";
import { makeToken } from "./token.js";

export const sessions = Router();
sessions.use(wajibPanitia); // semua rute di bawah ini khusus panitia

// Panitia hanya boleh melihat sesi miliknya sendiri.
function ambilSesi(req) {
  const s = db.prepare("SELECT * FROM sessions WHERE id = ? AND organizer_id = ?")
    .get(Number(req.params.id), req.organizerId);
  if (!s) throw gagal(404, "Sesi tidak ditemukan");
  return s;
}

sessions.get("/", (req, res) => {
  res.json(db.prepare(`
    SELECT s.id, s.title, s.created_at, s.closed_at, count(c.id) AS hadir
    FROM sessions s LEFT JOIN checkins c ON c.session_id = s.id
    WHERE s.organizer_id = ? GROUP BY s.id ORDER BY s.id DESC`).all(req.organizerId));
});

sessions.post("/", (req, res) => {
  const title = typeof req.body?.title === "string" ? req.body.title.trim() : "";
  if (title.length < 1 || title.length > 100) throw gagal(422, "Judul sesi wajib diisi, maksimal 100 karakter");
  const s = db.prepare("INSERT INTO sessions (organizer_id, title) VALUES (?, ?) RETURNING *").get(req.organizerId, title);
  res.status(201).json(s);
});

sessions.get("/:id", (req, res) => res.json(ambilSesi(req)));

sessions.post("/:id/close", (req, res) => {
  const s = ambilSesi(req);
  db.prepare("UPDATE sessions SET closed_at = unixepoch() WHERE id = ? AND closed_at IS NULL").run(s.id);
  res.json(ambilSesi(req));
});

// QR berisi token yang hanya berlaku di jendela waktu ini (plus satu jendela sebelumnya).
sessions.get("/:id/qr", async (req, res) => {
  const s = ambilSesi(req);
  if (s.closed_at) throw gagal(409, "Sesi sudah ditutup");
  const { token, expiresIn } = makeToken(s.id);
  const svg = await QRCode.toString(token, { type: "svg", margin: 1, errorCorrectionLevel: "M" });
  res.set("Cache-Control", "no-store").json({ svg, expiresIn });
});

