import { Router } from "express";
import { randomBytes } from "node:crypto";
import { db } from "./db.js";
import { bacaCookie, cookieAman, gagal } from "./http.js";
import { verifyToken } from "./token.js";

export const checkin = Router();
const SETAHUN = 365 * 24 * 60 * 60 * 1000;

checkin.post("/", (req, res) => {
  const { token, nim, name } = req.body ?? {};

  // 1. Tanda tangan dan jendela waktu
  const hasil = verifyToken(token);
  if (hasil.error) throw gagal(400, hasil.error);

  // 2. Sesi ada dan masih dibuka
  const s = db.prepare("SELECT id, title, closed_at FROM sessions WHERE id = ?").get(hasil.sessionId);
  if (!s) throw gagal(404, "Sesi tidak ditemukan");
  if (s.closed_at) throw gagal(409, "Sesi sudah ditutup panitia");

  // 3. Data peserta
  const cleanNim = typeof nim === "string" ? nim.trim().toUpperCase() : "";
  const cleanName = typeof name === "string" ? name.trim().replace(/\s+/g, " ") : "";
  const details = {};
  if (!/^[0-9A-Z]{5,20}$/.test(cleanNim)) details.nim = "NIM berisi 5 sampai 20 huruf atau angka";
  if (cleanName.length < 2 || cleanName.length > 80) details.name = "Nama 2 sampai 80 karakter";
  if (Object.keys(details).length) return res.status(422).json({ error: "Data belum lengkap", details });

  // 4. Cookie perangkat: satu HP hanya bisa dipakai absen sekali per sesi
  let device = bacaCookie(req, "perangkat");
  if (!/^[\w-]{22}$/.test(device ?? "")) {
    device = randomBytes(16).toString("base64url");
    res.cookie("perangkat", device, { ...cookieAman, maxAge: SETAHUN });
  }

  // 5. Simpan. Aturan UNIQUE di database yang menjaga NIM dan perangkat ganda.
  try {
    const row = db.prepare(`INSERT INTO checkins (session_id, nim, name, device_id) VALUES (?, ?, ?, ?)
      RETURNING id, nim, name, created_at`).get(s.id, cleanNim, cleanName, device);
    res.status(201).json({ session: s.title, checkin: row });
  } catch (err) {
    if (err.code !== "SQLITE_CONSTRAINT_UNIQUE") throw err;
    throw gagal(409, err.message.includes("checkins.nim")
      ? "NIM ini sudah tercatat hadir di sesi ini"
      : "HP ini sudah dipakai absen di sesi ini");
  }
});

