// Siapa saja yang sedang menonton daftar hadir, dikelompokkan per sesi.
// ponytail: disimpan di memori satu proses. Kalau server dijalankan lebih dari satu instance,
// ganti dengan Redis pub/sub atau Postgres LISTEN/NOTIFY.
const penonton = new Map(); // sessionId -> Set<res>

const kirimEvent = (res, event, data) => res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);

export function ikuti(req, res, sessionId, awal) {
  res.set({
    "Content-Type": "text/event-stream",
    "Cache-Control": "no-cache",
    "X-Accel-Buffering": "no", // minta proxy (nginx dan sejenisnya) tidak menahan data
  });
  res.flushHeaders();
  kirimEvent(res, "awal", awal); // daftar lengkap saat (ulang) tersambung

  if (!penonton.has(sessionId)) penonton.set(sessionId, new Set());
  penonton.get(sessionId).add(res);
  const detak = setInterval(() => res.write(": detak\n\n"), 25_000); // jaga koneksi tetap hidup

  req.on("close", () => {
    clearInterval(detak);
    penonton.get(sessionId)?.delete(res);
  });
}

export function kabarkan(sessionId, checkin) {
  for (const res of penonton.get(sessionId) ?? []) kirimEvent(res, "hadir", checkin);
}

