test("token: jendela sekarang dan sebelumnya diterima, yang lebih lama ditolak", () => {
  const t0 = 1_000_000 * WINDOW_MS + 5_000;
  const { token, expiresIn } = makeToken(7, t0);
  assert.equal(expiresIn, WINDOW_MS - 5_000);
  assert.equal(verifyToken(token, t0).sessionId, 7);
  assert.equal(verifyToken(token, t0 + WINDOW_MS).sessionId, 7);
  assert.match(verifyToken(token, t0 + 2 * WINDOW_MS).error, /kedaluwarsa/);
});

test("token: id sesi yang diubah membuat tanda tangan tidak cocok", () => {
  const { token } = makeToken(7);
  assert.match(verifyToken(token.replace(/^7\./, "8.")).error, /tidak sah/);
  assert.match(verifyToken("bukan-token").error, /tidak dikenali/);
});

